import json,os,stat,subprocess
from pathlib import Path
old=Path("/opt/hopper")
root=Path("/srv/projects/hopper")
def out(status,**kw):
 print(json.dumps(dict(status=status,**kw),ensure_ascii=True,sort_keys=True))
def active(name):
 q=subprocess.run(["/usr/bin/systemctl","is-active",name],capture_output=True,text=True,timeout=7)
 return q.stdout.strip()
services=["ssh","nginx","lowcost-europa","pink-vpn","pm2-iptvpn-bot","pm2-telegram-robot-leads"]
before={x:active(x) for x in services}
if not old.is_symlink() or os.readlink(old)!="/srv/projects/hopper":
 out("BLOCKED",reason="unexpected_or_absent_alias",changed=False)
elif root.is_symlink() or not root.is_dir() or not (root/"bin").is_dir() or not (root/"lib").is_dir():
 out("BLOCKED",reason="canonical_hopper_missing_or_not_physical",changed=False)
elif any(v!="active" for v in before.values()):
 out("BLOCKED",reason="service_not_active_before",services=before,changed=False)
else:
 roots=["/etc/systemd/system","/usr/lib/systemd/system","/etc/nginx","/etc/cron.d","/etc/cron.daily","/etc/cron.weekly","/usr/local/bin","/usr/local/sbin"]
 for n in ("telegram-robot-leads","iptvpn-bot","pink-iptv","lowcost-europa","fadego","skill-universal","Engenheira-reversa","REA-Trial","hopper","android-sdk","Codex","VPS"):
  for sub in ("deploy","scripts","bin","systemd","config"):
   roots.append("/srv/projects/"+n+"/"+sub)
  roots.append("/srv/projects/"+n)
 pruned={".git",".venv","venv","node_modules",".runtime","archive","backups","data","private","evidence","logs","tmp","dist","build",".npm",".gradle","__pycache__","releases","tests","docs","vendor","assets","test-results"}
 allowed={".py",".sh",".js",".json",".yml",".yaml",".service",".timer",".conf",".socket",".toml",".ini",".cfg",".ts"}
 matches=[];seen=set();count=0;limited=False
 for base in roots:
  if not os.path.isdir(base):continue
  # Every project root is inspected for immediate source files only.
  base_project=(base.startswith("/srv/projects/") and base.count("/")==3)
  if base_project:
   candidates=((base,[],[x.name for x in Path(base).iterdir() if x.is_file()]))
  else:
   candidates=os.walk(base,followlinks=False)
  for folder,dirs,files in candidates:
   dirs[:]=[d for d in dirs if d not in pruned and not d.startswith(".telegram-leads-") and d!="ferrari-requests"]
   for f in files:
    p=os.path.join(folder,f)
    if p in seen:continue
    seen.add(p);count+=1
    if count>12000:limited=True;break
    if Path(f).suffix.lower() not in allowed and f not in ("Dockerfile","Makefile","start.sh","stop.sh"):continue
    try:
     if not os.path.isfile(p) or os.stat(p).st_size>200000:continue
     if b"/opt/hopper" in Path(p).read_bytes():matches.append(p)
    except OSError:pass
   if limited:break
  if limited:break
 if limited or matches:
  out("BLOCKED",reason="scan_limit" if limited else "active_source_reference",changed=False,scanned=count,refs=matches[:12])
 else:
  try:
   old.unlink()
   after={x:active(x) for x in services}
   intact=(not old.exists() and not old.is_symlink() and root.is_dir() and (root/"bin").is_dir() and (root/"lib").is_dir() and after==before)
   if not intact:
    if not old.exists() and not old.is_symlink():os.symlink("/srv/projects/hopper",old)
    out("ROLLED_BACK",reason="postcheck_failed",changed=False,after=after)
   else:out("REMOVED",changed=True,old=str(old),canonical=str(root),scanned=count,services=after)
  except Exception as e:
   if not old.exists() and not old.is_symlink():os.symlink("/srv/projects/hopper",old)
   out("BLOCKED",changed=False,reason=type(e).__name__)
